function ldMeetingPlatform(url) {
  const u = String(url || "").toLowerCase();
  if (!u) return null;
  if (/teams\.microsoft|teams\.live|teams\.|microsoft/.test(u)) return {
    key: "teams",
    name: "Microsoft Teams",
    color: "#5059C9"
  };
  if (/zoom\./.test(u)) return {
    key: "zoom",
    name: "Zoom",
    color: "#2D8CFF"
  };
  if (/meet\.google|hangouts/.test(u)) return {
    key: "meet",
    name: "Google Meet",
    color: "#00897B"
  };
  if (/webex/.test(u)) return {
    key: "webex",
    name: "Webex",
    color: "#16A98D"
  };
  if (/whatsapp|wa\.me|chat\.whatsapp/.test(u)) return {
    key: "whatsapp",
    name: "WhatsApp",
    color: "#25D366"
  };
  if (/facebook|fb\.me|fb\.com|messenger/.test(u)) return {
    key: "facebook",
    name: "Facebook",
    color: "#1877F2"
  };
  if (/youtube|youtu\.be/.test(u)) return {
    key: "youtube",
    name: "YouTube Live",
    color: "#FF0000"
  };
  if (/intuition|percipio|skillsoft|coursera|udemy/.test(u)) return {
    key: "online",
    name: "Hosted platform",
    color: "#6941C6"
  };
  return {
    key: "online",
    name: "Online",
    color: "var(--brand-blue)"
  };
}
